/** Module for a command id, mirroring the firmware enum. */
export function moduleOfCmd(cmd: number): string {
  for (const [lo, hi, m] of DWARF_MODULE_RANGES) if (cmd >= lo && cmd < hi) return m;
  return 'NONE';
}

